		regex      bool
		pathName   string
		tagName    string
		editStr    string
		searchStr  string
		rmStr      string
		shell      string
		initFlag   bool
		confFlag   bool
		dirFlag    bool
		tagsFlag   bool
		updateFlag bool
		listFlag   bool
		version    bool
	)

