				return HandleSearch(searchStr, regex, colorize)
			}

			if editStr != "" {
				return HandleEdit(editStr)
			}

			if rmStr != "" {
				return HandleRemove(rmStr)
			}

			if listFlag || brief {
				return HandleList(args, listFlag, brief, pathName, tagName)
			}

			if len(args) > 0 {
				return ViewCheatsheet(args[0])
			}

			return EnsureConfig()
		},
		Args: cobra.MaximumNArgs(1),
	}

	// Persistent flags
	cmd.PersistentFlags().BoolVarP(&all, "all", "a", false, "Search among all cheatpaths")
	cmd.PersistentFlags().BoolVarP(&brief, "brief", "b", false, "List cheatsheets without file paths")
	cmd.PersistentFlags().BoolVarP(&colorize, "colorize", "c", false, "Colorize output")
	cmd.PersistentFlags().StringVarP(&pathName, "path", "p", "", "Return only sheets found on cheatpath name")
	cmd.PersistentFlags().StringVarP(&tagName, "tag", "t", "", "Return only sheets matching tag")
	cmd.PersistentFlags().BoolVarP(&regex, "regex", "r", false, "Treat search <phrase> as a regex")

	// Regular flags
	cmd.Flags().StringVarP(&editStr, "edit", "e", "", "Edit cheatsheet")
	cmd.Flags().StringVarP(&searchStr, "search", "s", "", "Search cheatsheets for phrase")
	cmd.Flags().StringVarP(&rmStr, "rm", "", "", "Remove (delete) cheatsheet")
	cmd.Flags().StringVarP(&shell, "completion", "", "", "Generate shell completion script (shell: bash, zsh, fish, powershell)")

	// Bool flags
	cmd.Flags().BoolVar(&initFlag, "init", false, "Write a default config file to stdout")
	cmd.Flags().BoolVar(&confFlag, "conf", false, "Display the config file path")
	cmd.Flags().BoolVarP(&dirFlag, "directories", "d", false, "List cheatsheet directories")
	cmd.Flags().BoolVarP(&tagsFlag, "tags", "T", false, "List all tags in use")
	cmd.Flags().BoolVarP(&updateFlag, "update", "u", false, "Update git-backed cheatpaths")
	cmd.Flags().BoolVarP(&listFlag, "list", "l", false, "List cheatsheets")
	cmd.Flags().BoolVarP(&version, "version", "v", false, "Print the version number")

	return cmd
}

func buildExamples() string {
	return `  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

  To view the tar cheatsheet:
    cheat tar

  To edit (or create) the foo cheatsheet:
    cheat -e foo

  To edit (or create) the foo/bar cheatsheet on the "work" cheatpath:
    cheat -p work -e foo/bar

  To view all cheatsheet directories:
    cheat -d

  To list all available cheatsheets:
    cheat -l

  To briefly list all cheatsheets whose titles match "apt":
    cheat -b apt

  To list all tags in use:
    cheat -T

  To list available cheatsheets that are tagged as "personal":
