	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

type CheatpathConfig struct {
	Name     string   `yaml:"name"`
	Path     string   `yaml:"path"`
	Tags     []string `yaml:"tags"`
	Readonly bool     `yaml:"readonly"`
}

type Config struct {
	Editor    string            `yaml:"editor"`
	Colorize  bool              `yaml:"colorize"`
	Style     string            `yaml:"style"`
	Formatter string            `yaml:"formatter"`
	Pager     string            `yaml:"pager"`
	Cheatpaths []CheatpathConfig `yaml:"cheatpaths"`
}

type Cheatsheet struct {
	Title    string
	Path     string
	Tags     []string
	Content  string
	Syntax   string
	Metadata map[string]interface{}
}

func LoadConfig() (*Config, error) {
	configPath := GetConfigPath()
	content, err := ioutil.ReadFile(configPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read config: %w", err)
	}

	var cfg Config
	if err := yaml.Unmarshal(content, &cfg); err != nil {
		return nil, fmt.Errorf("failed to parse config: %w", err)
	}

	// Validate and filter cheatpaths
	var validPaths []CheatpathConfig
	for _, cp := range cfg.Cheatpaths {
		expandedPath := os.ExpandEnv(cp.Path)
		if _, err := os.Stat(expandedPath); err == nil {
			cp.Path = expandedPath
			validPaths = append(validPaths, cp)
		} else {
			fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' does not exist, skipping\n", cp.Path)
		}
	}
	cfg.Cheatpaths = validPaths

	return &cfg, nil
}

func GetAllCheatsheets() ([]Cheatsheet, error) {
	cfg, err := LoadConfig()
	if err != nil {
		return nil, err
	}

	var sheets []Cheatsheet
	seen := make(map[string]bool)

	// Process cheatpaths in reverse order so later paths override earlier ones
	for i := len(cfg.Cheatpaths) - 1; i >= 0; i-- {
		cp := cfg.Cheatpaths[i]
		sheets, err = loadCheatsheetFromPath(cp, sheets, seen)
		if err != nil {
			return nil, err
		}
	}

	return sheets, nil
}

func loadCheatsheetFromPath(cp CheatpathConfig, existing []Cheatsheet, seen map[string]bool) ([]Cheatsheet, error) {
	files, err := ioutil.ReadDir(cp.Path)
	if err != nil {
		return existing, nil
	}

	for _, file := range files {
		if file.IsDir() || strings.HasPrefix(file.Name(), ".") {
			continue
		}

		title := file.Name()
		if !seen[title] {
			sheetPath := filepath.Join(cp.Path, file.Name())
			content, _ := ioutil.ReadFile(sheetPath)
			sheet := parseCheatsheet(title, sheetPath, string(content))

			// Add path tags to sheet tags
			allTags := append([]string{}, cp.Tags...)
			allTags = append(allTags, sheet.Tags...)
			sheet.Tags = allTags

			existing = append(existing, sheet)
			seen[title] = true
		}
	}

	return existing, nil
}

func parseCheatsheet(title, path, content string) Cheatsheet {
	sheet := Cheatsheet{
		Title:    title,
		Path:     path,
		Content:  content,
		Metadata: make(map[string]interface{}),
	}

	// Check for YAML frontmatter
	if strings.HasPrefix(content, "---\n") || strings.HasPrefix(content, "---\r\n") {
		endIdx := strings.Index(content[4:], "---")
		if endIdx != -1 {
			frontmatter := content[4 : endIdx+4]
			var meta map[string]interface{}
			if err := yaml.Unmarshal([]byte(frontmatter), &meta); err == nil {
				sheet.Metadata = meta

				if tags, ok := meta["tags"]; ok {
					switch v := tags.(type) {
					case []interface{}:
						for _, tag := range v {
							if s, ok := tag.(string); ok {
								sheet.Tags = append(sheet.Tags, s)
							}
						}
					}
				}

				if syntax, ok := meta["syntax"]; ok {
					if s, ok := syntax.(string); ok {
						sheet.Syntax = s
					}
				}
			}

			sheet.Content = content[endIdx+7:]
		}
	}

	return sheet
}

