func FilterCheatsheets(sheets []Cheatsheet, pathFilter, tagFilter, titleFilter string) []Cheatsheet {
	var filtered []Cheatsheet

	for _, sheet := range sheets {
		// Filter by path
		if pathFilter != "" {
			found := false
			for _, path := range sheet.Tags {
				if path == pathFilter {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}

		// Filter by tag
		if tagFilter != "" {
			found := false
			for _, tag := range sheet.Tags {
				if tag == tagFilter {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}

		// Filter by title
		if titleFilter != "" {
			if !strings.Contains(strings.ToLower(sheet.Title), strings.ToLower(titleFilter)) {
				continue
			}
		}

		filtered = append(filtered, sheet)
	}

	// Sort by title
	sort.Slice(filtered, func(i, j int) bool {
		return filtered[i].Title < filtered[j].Title
	})

	return filtered
