				sheet.Metadata = meta

				if tags, ok := meta["tags"]; ok {
					switch v := tags.(type) {
					case []interface{}:
						for _, tag := range v {
							if s, ok := tag.(string); ok {
								sheet.Tags = append(sheet.Tags, s)
							}
						}
					}
				}

				if syntax, ok := meta["syntax"]; ok {
					if s, ok := syntax.(string); ok {
						sheet.Syntax = s
					}
				}
			}

			sheet.Content = content[endIdx+7:]
		}
	}

	return sheet
}

func GetCheatsheetByName(name string) (*Cheatsheet, error) {
	sheets, err := GetAllCheatsheets()
	if err != nil {
		return nil, err
	}

	for _, sheet := range sheets {
		if sheet.Title == name {
			return &sheet, nil
		}
	}

	return nil, fmt.Errorf("cheatsheet '%s' not found", name)
}

func FilterCheatsheets(sheets []Cheatsheet, pathFilter, tagFilter, titleFilter string) []Cheatsheet {
	var filtered []Cheatsheet

	for _, sheet := range sheets {
		// Filter by path
		if pathFilter != "" {
			found := false
			for _, path := range sheet.Tags {
				if path == pathFilter {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}

		// Filter by tag
		if tagFilter != "" {
			found := false
			for _, tag := range sheet.Tags {
				if tag == tagFilter {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}

		// Filter by title
		if titleFilter != "" {
			if !strings.Contains(strings.ToLower(sheet.Title), strings.ToLower(titleFilter)) {
				continue
			}
		}

		filtered = append(filtered, sheet)
	}

	// Sort by title
	sort.Slice(filtered, func(i, j int) bool {
		return filtered[i].Title < filtered[j].Title
	})

	return filtered
}

func SearchCheatsheets(phrase string, isRegex bool) ([]Cheatsheet, error) {
	sheets, err := GetAllCheatsheets()
	if err != nil {
		return nil, err
	}

	var results []Cheatsheet

	for _, sheet := range sheets {
		matches := false

		if isRegex {
			re, err := regexp.Compile(phrase)
			if err != nil {
				continue
			}
			if re.MatchString(sheet.Content) {
				matches = true
			}
		} else {
			if strings.Contains(sheet.Content, phrase) {
				matches = true
			}
		}

		if matches {
			results = append(results, sheet)
		}
	}

	return results, nil
}

func GetAllTags() ([]string, error) {
	sheets, err := GetAllCheatsheets()
	if err != nil {
		return nil, err
	}

	tagMap := make(map[string]bool)
	for _, sheet := range sheets {
		for _, tag := range sheet.Tags {
			tagMap[tag] = true
		}
	}

	var tags []string
	for tag := range tagMap {
		tags = append(tags, tag)
	}

	sort.Strings(tags)
	return tags, nil
}
