package main

import (
	"bufio"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"strings"
)

type CheatpathConfig struct {
	Name     string
	Path     string
	Tags     []string
	Readonly bool
}

type Config struct {
	Editor    string
	Colorize  bool
	Style     string
	Formatter string
	Pager     string
	Cheatpaths []CheatpathConfig
}

func LoadConfig() (*Config, error) {
	configPath := GetConfigPath()
	content, err := ioutil.ReadFile(configPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read config: %w", err)
	}

	cfg := parseSimpleYAML(string(content))

	// Validate and filter cheatpaths
	var validPaths []CheatpathConfig
	for _, cp := range cfg.Cheatpaths {
		expandedPath := os.ExpandEnv(cp.Path)
		if _, err := os.Stat(expandedPath); err == nil {
			cp.Path = expandedPath
			validPaths = append(validPaths, cp)
		} else {
			fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' does not exist, skipping\n", cp.Path)
		}
	}
	cfg.Cheatpaths = validPaths

	return cfg, nil
}

func parseSimpleYAML(content string) *Config {
	cfg := &Config{
		Colorize:  false,
		Style:     "monokai",
		Formatter: "terminal256",
		Pager:     "cat",
	}

	scanner := bufio.NewScanner(strings.NewReader(content))
	inCheatpaths := false
	currentPath := &CheatpathConfig{}

	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)

		if strings.HasPrefix(trimmed, "#") {
			continue
		}

		if strings.HasPrefix(trimmed, "editor:") {
			cfg.Editor = strings.TrimSpace(strings.TrimPrefix(trimmed, "editor:"))
		} else if strings.HasPrefix(trimmed, "colorize:") {
			cfg.Colorize = strings.Contains(trimmed, "true")
		} else if strings.HasPrefix(trimmed, "style:") {
			cfg.Style = strings.TrimSpace(strings.TrimPrefix(trimmed, "style:"))
		} else if strings.HasPrefix(trimmed, "formatter:") {
			cfg.Formatter = strings.TrimSpace(strings.TrimPrefix(trimmed, "formatter:"))
		} else if strings.HasPrefix(trimmed, "pager:") {
			cfg.Pager = strings.TrimSpace(strings.TrimPrefix(trimmed, "pager:"))
		} else if trimmed == "cheatpaths:" {
			inCheatpaths = true
		} else if inCheatpaths {
			if strings.HasPrefix(trimmed, "- name:") {
				if currentPath.Name != "" {
					cfg.Cheatpaths = append(cfg.Cheatpaths, *currentPath)
				}
				currentPath = &CheatpathConfig{}
				currentPath.Name = strings.TrimSpace(strings.TrimPrefix(trimmed, "- name:"))
			} else if strings.HasPrefix(trimmed, "name:") {
				if currentPath.Name != "" {
					cfg.Cheatpaths = append(cfg.Cheatpaths, *currentPath)
				}
				currentPath = &CheatpathConfig{}
				currentPath.Name = strings.TrimSpace(strings.TrimPrefix(trimmed, "name:"))
			} else if strings.HasPrefix(trimmed, "path:") {
				currentPath.Path = strings.TrimSpace(strings.TrimPrefix(trimmed, "path:"))
			} else if strings.HasPrefix(trimmed, "tags:") {
				tagsStr := strings.TrimSpace(strings.TrimPrefix(trimmed, "tags:"))
				tagsStr = strings.Trim(tagsStr, "[]")
				tags := strings.Split(tagsStr, ",")
				for _, tag := range tags {
					currentPath.Tags = append(currentPath.Tags, strings.TrimSpace(tag))
				}
			} else if strings.HasPrefix(trimmed, "readonly:") {
				currentPath.Readonly = strings.Contains(trimmed, "true")
			}
		}
	}

	if currentPath.Name != "" {
		cfg.Cheatpaths = append(cfg.Cheatpaths, *currentPath)
	}

	return cfg
}

func GetConfigPath() string {
	// Check CHEAT_CONFIG_PATH
	if path := os.Getenv("CHEAT_CONFIG_PATH"); path != "" {
		return path
	}

	// Check XDG_CONFIG_HOME
	if xdgConfig := os.Getenv("XDG_CONFIG_HOME"); xdgConfig != "" {
		configPath := filepath.Join(xdgConfig, "cheat", "conf.yml")
		if _, err := os.Stat(configPath); err == nil {
			return configPath
		}
	}

	// Check ~/.config/cheat/conf.yml
	if home := os.Getenv("HOME"); home != "" {
		configPath := filepath.Join(home, ".config", "cheat", "conf.yml")
		if _, err := os.Stat(configPath); err == nil {
			return configPath
		}
		// Check ~/.cheat/conf.yml
		configPath = filepath.Join(home, ".cheat", "conf.yml")
		if _, err := os.Stat(configPath); err == nil {
			return configPath
		}
		// Return default
		return filepath.Join(home, ".config", "cheat", "conf.yml")
	}

	// Fallback
	return "/etc/cheat/conf.yml"
}

func GetDefaultConfig() string {
	home := os.Getenv("HOME")
	if home == "" {
		home = "/home/user"
	}

	return `---
# The editor to use with 'cheat -e <sheet>'. Overridden by $VISUAL or $EDITOR.
editor: EDITOR_PATH

# Should 'cheat' always colorize output?
colorize: false

# Which 'chroma' colorscheme should be applied to the output?
# Options are available here:
#   https://github.com/alecthomas/chroma/tree/master/styles
style: monokai

# Which 'chroma' "formatter" should be applied?
# One of: "terminal", "terminal256", "terminal16m"
formatter: terminal256

# Through which pager should output be piped?
# 'less -FRX' is recommended on Unix systems
# 'more' is recommended on Windows
pager: cat

# The paths at which cheatsheets are available. Tags associated with a cheatpath
# are automatically attached to all cheatsheets residing on that path.
#
# Whenever cheatsheets share the same title (like 'tar'), the most local
# cheatsheets (those which come later in this file) take precedence over the
# less local sheets. This allows you to create your own "overides" for
# "upstream" cheatsheets.
#
# But what if you want to view the "upstream" cheatsheets instead of your own?
# Cheatsheets may be filtered by 'tags' in combination with the '--tag' flag.
# 
# Example: 'cheat tar --tag=community' will display the 'tar' cheatsheet that
# is tagged as 'community' rather than your own.
#
# Paths that come earlier are considered to be the most "global", and paths
# that come later are considered to be the most "local". The most "local" paths
# take precedence.
#
# See: https://github.com/cheat/cheat/blob/master/doc/cheat.1.md#cheatpaths
cheatpaths:

  # Cheatsheets that are tagged "personal" are stored here by default:
  - name: personal
    path: ` + home + `/.config/cheat/cheatsheets/personal
    tags: [ personal ]
    readonly: false

  # Cheatsheets that are tagged "work" are stored here by default:
  - name: work
    path: ` + home + `/.config/cheat/cheatsheets/work
    tags: [ work ]
    readonly: false

  # Community cheatsheets (https://github.com/cheat/cheatsheets):
  # To install: git clone https://github.com/cheat/cheatsheets ` + home + `/.config/cheat/cheatsheets/community
  #- name: community
  #  path: ` + home + `/.config/cheat/cheatsheets/community
  #  tags: [ community ]
  #  readonly: true

  # You can also use glob patterns to automatically load cheatsheets from all
  # directories that match.
  #
  # Example: overload cheatsheets for projects under ~/src/github.com/example/*/
  #- name: example-projects
  #  path: ~/src/github.com/example/**/.cheat
  #  tags: [ example ]
  #  readonly: true
`
}
EOF

