package main

import (
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"text/tabwriter"
)

func ListDirectories() error {
	cfg, err := LoadConfig()
	if err != nil {
		return err
	}

	for _, cp := range cfg.Cheatpaths {
		fmt.Printf("%s: %s\n", cp.Name, cp.Path)
	}

	return nil
}

func ListTags() error {
	tags, err := GetAllTags()
	if err != nil {
		return err
	}

	for _, tag := range tags {
		fmt.Println(tag)
	}

	return nil
}

func UpdateCheatpaths() error {
	return fmt.Errorf("not implemented")
}

func ViewCheatsheet(name string) error {
	sheet, err := GetCheatsheetByName(name)
	if err != nil {
		return fmt.Errorf("cheatsheet '%s' not found", name)
	}

	fmt.Print(sheet.Content)
	return nil
}

func HandleList(args []string, isFull, isBrief bool, pathFilter, tagFilter string) error {
	sheets, err := GetAllCheatsheets()
	if err != nil {
		return err
	}

	// If an argument is provided, filter by title
	titleFilter := ""
	if len(args) > 0 {
		titleFilter = args[0]
	}

	filtered := FilterCheatsheets(sheets, pathFilter, tagFilter, titleFilter)

	if isBrief {
		// Brief format: just title and tags
		w := tabwriter.NewWriter(os.Stdout, 0, 0, 1, ' ', 0)
		fmt.Fprint(w, "title: tags:\n")
		for _, sheet := range filtered {
			fmt.Fprintf(w, "%s\t%s\n", sheet.Title, strings.Join(sheet.Tags, ","))
		}
		w.Flush()
	} else {
		// Full format: title, file path, and tags
		w := tabwriter.NewWriter(os.Stdout, 0, 0, 1, ' ', 0)
		fmt.Fprint(w, "title: file:\ttags:\n")
		for _, sheet := range filtered {
			fmt.Fprintf(w, "%s\t%s\t%s\n", sheet.Title, sheet.Path, strings.Join(sheet.Tags, ","))
		}
		w.Flush()
	}

	return nil
}

func HandleSearch(phrase string, isRegex, doColorize bool) error {
	results, err := SearchCheatsheets(phrase, isRegex)
	if err != nil {
		return err
	}

	for i, sheet := range results {
		if i > 0 {
			fmt.Println()
		}

		// Print title with path in parentheses
		pathTag := "personal"
		if len(sheet.Tags) > 0 {
			pathTag = sheet.Tags[len(sheet.Tags)-1]
		}
		fmt.Printf("%s \033[2m(%s)\033[0m\n", sheet.Title, pathTag)

		// Print content
		content := sheet.Content
		if doColorize {
			content = colorizeContent(content, sheet.Syntax)
		} else {
			// Highlight matches if not colorizing
			if !isRegex {
				re := regexp.MustCompile("(?i)" + regexp.QuoteMeta(phrase))
				content = re.ReplaceAllStringFunc(content, func(match string) string {
					return "\033[38;5;81m" + match + "\033[0m"
				})
			}
		}

